// widgets/recommendation_banner.dart
// Animated recommendation banner shown at the top of the running dashboard
// when SessionProvider emits a new coaching tip.

import 'package:flutter/material.dart';

/// A prominent, dismissible banner that surfaces real-time running recommendations.
///
/// [message] is the coaching text generated by [SessionProvider].
/// [onDismiss] is called when the user taps the close button.
///
/// The banner uses an AnimatedSwitcher internally so it slides in smoothly
/// whenever [message] changes.
class RecommendationBanner extends StatelessWidget {
  const RecommendationBanner({
    super.key,
    required this.message,
    required this.onDismiss,
  });

  final String message;
  final VoidCallback onDismiss;

  @override
  Widget build(BuildContext context) {
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 350),
      transitionBuilder: (child, animation) => SlideTransition(
        position: Tween<Offset>(
          begin: const Offset(0, -1),
          end: Offset.zero,
        ).animate(CurvedAnimation(parent: animation, curve: Curves.easeOut)),
        child: FadeTransition(opacity: animation, child: child),
      ),
      child: _BannerContent(
        key: ValueKey(message),
        message: message,
        onDismiss: onDismiss,
      ),
    );
  }
}

/// Inner content widget — keyed on [message] so AnimatedSwitcher detects changes.
class _BannerContent extends StatelessWidget {
  const _BannerContent({
    super.key,
    required this.message,
    required this.onDismiss,
  });

  final String message;
  final VoidCallback onDismiss;

  @override
  Widget build(BuildContext context) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(16, 12, 8, 12),
      decoration: BoxDecoration(
        // Eye-catching gradient — orange accent on dark background
        gradient: const LinearGradient(
          colors: [Color(0xFF2A1A00), Color(0xFF1A1A2E)],
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
        ),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: const Color(0xFFFF9100).withOpacity(0.6),
          width: 1.5,
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFFFF9100).withOpacity(0.2),
            blurRadius: 12,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // ── Icon ────────────────────────────────────────────────────
          const Padding(
            padding: EdgeInsets.only(top: 2),
            child: Icon(
              Icons.tips_and_updates_outlined,
              color: Color(0xFFFF9100),
              size: 22,
            ),
          ),

          const SizedBox(width: 12),

          // ── Message text ─────────────────────────────────────────────
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'RECOMENDACIÓN',
                  style: TextStyle(
                    color: Color(0xFFFF9100),
                    fontSize: 9,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 1.5,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  message,
                  style: const TextStyle(
                    color: Color(0xFFFFFFFF),
                    fontSize: 13,
                    fontWeight: FontWeight.w500,
                    height: 1.4,
                  ),
                ),
              ],
            ),
          ),

          // ── Dismiss button ───────────────────────────────────────────
          GestureDetector(
            onTap: onDismiss,
            child: const Padding(
              padding: EdgeInsets.all(4),
              child: Icon(
                Icons.close,
                color: Color(0xFFB0BEC5),
                size: 18,
              ),
            ),
          ),
        ],
      ),
    );
  }
}
